; ============================================================
; Bank $CF: the data the code source does not emit
;
; Generated by tools/extract_data.py from symbols/data_survey.csv;
; do not edit (run `python3 tools/extract_data.py generate`). Each
; piece is a row of the survey (its kind, format, readers and
; confidence are there) at its address. fill and pointer tables are
; source; incbin reads an asset that tools/extract_data.py writes
; from your own ROM to build/assets/, a pack tools/build_rom.py
; makes from one in build/packs/ (event scripts assembled from
; their disassembly first), or text or records it encodes into
; build/text/ and build/records/ (symbols/data_assets.csv lists
; them; nothing here is ROM data).
; ============================================================

; $CF:0000-$CF:7FFF (32,768 B), graphics, confirmed: 2bpp tile graphics: entry tile * 8
; Read by BattleCD_TileCopy2.
org $CF0000
BattleRom_FxTileGfx:
    incbin "../../build/assets/graphics/BattleRom_FxTileGfx.bin"

; $CF:8000-$CF:9FFF (8,192 B), table, confirmed: 64 u16 tile entries per layer-3 tile set
; Read by BattleCD_LoadFxTiles.
org $CF8000
BattleRom_FxTileLists:
    incbin "../../build/assets/table/BattleRom_FxTileLists.bin"

; $CF:A000-$CF:DFFF (16,384 B), table, confirmed: 32 u16 tile entries per action graphics set
; Read by BattleCD_ConvertFxGfx.
org $CFA000
BattleRom_FxGfxLists:
    incbin "../../build/assets/table/BattleRom_FxGfxLists.bin"

; $CF:E000-$CF:E1FF (512 B), table, confirmed: 2 B per action graphics set: four 2-bit colour
; fields per byte
; Read by BattleCD_ConvertFxGfx.
org $CFE000
BattleRom_FxGfxColours:
    incbin "../../build/assets/table/BattleRom_FxGfxColours.bin"

; $CF:E200-$CF:E27F (128 B), table, confirmed: bitmaps by tile word + tile row: tiles that get
; palette bit !BattleCD_FxAttrPal
; Read by BattleCD_BuildFxTilemap.
org $CFE200
BattleRom_FxPalBits:
    incbin "../../build/assets/table/BattleRom_FxPalBits.bin"

; $CF:E280-$CF:E2FF (128 B), padding, probable: 128 x $FF
org $CFE280
Padding_CFE280:
    fillbyte $FF
    fill 128
